ns16:extensionElements.ns2:postAssignmentScript:
if(tw.local.odcRequest.requestNature.value == tw.epv.RequestNature.NewRequest)
{
	tw.local.valid = true;
	tw.local.errorMessage ="";
}

if(tw.local.odcRequest.CustomerInfo.customerType !="" && tw.local.odcRequest.CustomerInfo.customerType == "C")
{
	tw.local.odcRequest.CustomerInfo.customerType = "Corporate";
}
else
{
	tw.local.odcRequest.CustomerInfo.customerType = "Individual";
}


tw.local.requestNature = tw.local.odcRequest.requestNature.value;
tw.local.requestType = tw.local.odcRequest.requestType.value;
tw.local.customerInfo = tw.local.odcRequest.CustomerInfo;

if(!!tw.local.errorMessage){
	tw.local.isSuccessful = false
	tw.local.errorPnlVis = "EDITABLE";
}else{
	tw.local.errorPnlVis = "NONE";
	tw.local.odcRequest.customerName = tw.local.odcRequest.CustomerInfo.customerName;
}

ns16:scriptTask.ns16:script:
tw.local.isSuccessful=false;
tw.local.error = {};
tw.local.errorPnlVis= "NONE";

//tw.local.odcRequest={};
tw.local.odcRequest.appInfo = {};
var date = new Date();
tw.local.odcRequest.appInfo.requestDate =  date.getDate()+'/' +(date.getMonth() + 1) + '/' + date.getFullYear();



tw.local.odcRequest.appInfo.branch = {};

	tw.local.odcRequest.appInfo.initiator = tw.system.user.fullName+"( "+ tw.system.user.name+")";
	tw.local.odcRequest.appInfo.requestName = "Outward Documentary Collection";
	tw.local.odcRequest.appInfo.stepName =  "Start New ODC Request";
	tw.local.odcRequest.appInfo.status ="New ";
	tw.local.odcRequest.appInfo.subStatus ="New ";
	if( tw.local.routingDetails.hubCode !=null)
	{
		tw.local.odcRequest.appInfo.branch.name = "HUB "   + tw.local.routingDetails.hubCode;
		tw.local.odcRequest.appInfo.branch.value =  "HUB " + tw.local.routingDetails.hubCode;
		
		tw.local.role = "hub";
		tw.local.odcRequest.InitiatorHubBranch =tw.local.odcRequest.appInfo.branch.value;
	}
	else
	{
		tw.local.odcRequest.appInfo.branch.name  =  tw.local.routingDetails.branchName;
		tw.local.odcRequest.appInfo.branch.value =  tw.local.routingDetails.branchName;
		tw.local.role = "branch";
		tw.local.odcRequest.InitiatorHubBranch =tw.local.odcRequest.appInfo.branch.value;
	}
	
tw.local.actionConditins ="new";

tw.local.newRequest = ""+tw.epv.RequestNature.NewRequest;
tw.local.odcRequest.requestNature = {};
tw.local.odcRequest.requestNature.value = tw.epv.RequestNature.NewRequest;

tw.local.errorMessage ="";
var mandatoryTriggered = false;
/************************************************************************************************************************
/*-------------------------------------------------- Validation Functions ------------------------------------------
************************************************************************************************************************/
/*
* =========================================================================================================
*  
* Add a coach validation error 
* 		
* EX:	addError(tw.local.name , 'this is a control validation message!' , 'this is a validation message!');
*
* =========================================================================================================
*/
function addError(fieldName , controlMessage , validationMessage , fromMandatory)
{
	tw.system.coachValidation.addValidationError(fieldName, controlMessage);
	fromMandatory && mandatoryTriggered ? "" : tw.local.errorMessage += "<li>" + validationMessage + "</li>";
}

/*
* =================================================================================================================================
*
* Add a coach validation error if the string length is less than given length
*	
* EX:	minLength(tw.local.name , 'tw.local.name' , 10 , 'this is a control validation message!' , 'this is a validation message!')
*
* =================================================================================================================================
*/

function minLength(field , fieldName , len , controlMessage , validationMessage)
{
	if (field != null && field != undefined && field.length < len)
	{
		addError(fieldName , controlMessage , validationMessage);
		return false;
	}
	return true;
}

/*
* =======================================================================================================================
*
* Add a coach validation error if the string length is greater than given length
*	
* EX:	maxLength(tw.local.name , 'tw.local.name' , 14 , 'this is a validation message!' , 'this is a validation message!')
*
* =======================================================================================================================
*/

function maxLength(field , fieldName , len , controlMessage , validationMessage)
{
	if (field != null && field != undefined && field.length > len)
	{
		addError(fieldName , controlMessage , validationMessage);
		return false;
	}
	return true;
}
/*
* ==================================================================================================================
*
* Add a coach validation error if the field is null 'Mandatory'
*	
* EX:	notNull(tw.local.name , 'tw.local.name')
*
* ==================================================================================================================
*/

function mandatory(field , fieldName)
{
	if (field == null || field == undefined )
	{
		addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
		mandatoryTriggered = true;
		return false;
	}
	else
	{
		switch (typeof field)
		{
			case "string":
				if (field.trim() != undefined && field.trim() != null && field.trim().length == 0)
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;
				}
				break;
			case "number":
				if (field == 0.0)
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;
				}
				if (field < 0)
				{
					var msg= "Invalid Value, This field can not be negative value.";
					addError(fieldName , msg , msg , true);
					mandatoryTriggered = true;
					return false;
				}
				break;
		}
	}
	return true;
}


